tool_input.command:
cat > test-threshold.mjs << 'EOF'
import fs from 'fs';
import path from 'path';
import os from 'os';
import { fileURLToPath } from 'url';
import { Eval } from './packages/frai-core/src/index.js';

const __dir = path.dirname(fileURLToPath(import.meta.url));
const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-threshold-test-'));

// Create test data
const outputs = ['hello world', 'test output', 'another test'];
const references = ['hello world', 'test output', 'another test'];

fs.writeFileSync(path.join(tmpDir, 'outputs.json'), JSON.stringify(outputs));
fs.writeFileSync(path.join(tmpDir, 'references.json'), JSON.stringify(references));

// Test 1: Load dataset
const dataset = Eval.loadDataset({
  outputsPath: path.join(tmpDir, 'outputs.json'),
  referencesPath: path.join(tmpDir, 'references.json')
});

console.log('✓ Dataset loaded');

// Test 2: Run evaluations
const evaluations = Eval.runEvaluations({
  outputs: dataset.outputs,
  references: dataset.references
});

console.log('✓ Evaluations run');
console.log('  - exact_match score:', evaluations[0].score);

// Test 3: Generate report with passing thresholds
const reportPass = Eval.generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: { exact_match: 0.9, toxicity: 0.5 }
});

console.log('✓ Report with passing thresholds generated');
console.log('  - passed:', reportPass.passed);
console.log('  - thresholds:', reportPass.thresholds.map(t => ({ metric: t.metric, passed: t.passed })));

// Test 4: Generate report with failing thresholds
const reportFail = Eval.generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: { exact_match: 0.99 }
});

console.log('✓ Report with failing thresholds generated');
console.log('  - passed:', reportFail.passed);
console.log('  - thresholds:', reportFail.thresholds.map(t => ({ metric: t.metric, passed: t.passed })));

// Test 5: Write JSON report
const jsonPath = Eval.writeReport({
  report: reportPass,
  format: 'json',
  reportPath: path.join(tmpDir, 'report.json')
});

console.log('✓ JSON report written:', jsonPath);

// Test 6: Write Markdown report with thresholds
const mdPath = Eval.writeReport({
  report: reportPass,
  format: 'markdown',
  reportPath: path.join(tmpDir, 'report.md')
});

const mdContent = fs.readFileSync(mdPath, 'utf8');
if (mdContent.includes('## Thresholds')) {
  console.log('✓ Markdown report includes Thresholds section');
} else {
  console.log('✗ Markdown report missing Thresholds section');
  console.log(mdContent);
}

// Cleanup
fs.rmSync(tmpDir, { recursive: true, force: true });

console.log('\n✓ All tests passed!');
EOF
node test-threshold.mjs
